<script setup>
import {onMounted,ref,computed,watch} from 'vue'
import axios from 'axios'
const scope=ref('assistant'), configs=ref(null), snapshots=ref({}), action=ref(''), loading=ref(true), error=ref(''), notice=ref(''), showKey=ref(false), form=ref()
const busy=computed(()=>!!action.value)
const current=computed(()=>configs.value?.[scope.value])
const dirty=computed(()=>current.value&&JSON.stringify(current.value)!==JSON.stringify(snapshots.value[scope.value]))
const addressChanged=computed(()=>current.value&&current.value.url!==snapshots.value[scope.value]?.url)
function record(value){return {...value,api_key:'',clear_key:false}}
function adopt(data){configs.value=Object.fromEntries(Object.entries(data).map(([key,value])=>[key,record(value)]));snapshots.value=JSON.parse(JSON.stringify(configs.value))}
async function load(){loading.value=true;error.value='';try{adopt((await axios.get('/api/settings/models')).data)}catch(e){error.value=e.response?.status===404?'后端尚未加载大模型设置接口，请重启后端后重新打开设置。':'配置读取失败，请检查后端连接。'}finally{loading.value=false}}
function switchScope(value){scope.value=value;showKey.value=false;error.value='';notice.value=''}
function reset(){configs.value[scope.value]={...snapshots.value[scope.value]};showKey.value=false;error.value='';notice.value=''}
watch(()=>current.value&&JSON.stringify(current.value),()=>{error.value='';notice.value=''})
async function submit(test=false){if(!current.value||busy.value||!form.value.reportValidity())return;const selected=scope.value,item=current.value;action.value=test?'test':'save';error.value='';notice.value='';try{const payload={url:item.url,model:item.model,api_key:item.api_key,clear_key:item.clear_key};if(test){notice.value=(await axios.post(`/api/settings/models/${selected}/test`,payload)).data.message}else{const data=(await axios.put(`/api/settings/models/${selected}`,payload)).data;configs.value[selected]=record(data[selected]);snapshots.value[selected]=record(data[selected]);showKey.value=false;await Promise.resolve();notice.value='已保存，新请求立即生效。'}}catch(e){const detail=e.response?.data?.detail;error.value=typeof detail==='string'?detail:'操作失败，请检查配置和后端连接。'}finally{action.value=''}}
onMounted(load)
</script>
<template>
<section class="model-settings" :aria-busy="loading||busy">
  <nav class="model-scopes" aria-label="模型用途">
    <button type="button" :disabled="busy" :aria-pressed="scope==='assistant'" :class="{active:scope==='assistant'}" @click="switchScope('assistant')"><span class="model-scope-icon">AI</span><span><b>AI 助手</b><small>对话与工具操作</small></span></button>
    <button type="button" :disabled="busy" :aria-pressed="scope==='ocr'" :class="{active:scope==='ocr'}" @click="switchScope('ocr')"><span class="model-scope-icon">OCR</span><span><b>OCR 多模态</b><small>PDF 图片文字识别</small></span></button>
  </nav>
  <div v-if="loading" class="model-loading" role="status">正在读取模型配置…</div>
  <form v-else-if="current" ref="form" @submit.prevent="submit()">
    <div class="model-heading"><b>连接配置</b><span :class="{unsaved:dirty}">{{dirty?'有未保存的修改':current.source==='settings'?'已保存配置':current.url && current.model?'使用环境配置':'尚未配置'}}</span></div>
    <fieldset :disabled="busy">
      <label for="model-endpoint">接口地址 <span>必填</span></label>
      <input id="model-endpoint" v-model.trim="current.url" type="url" required placeholder="https://api.example.com/v1/chat/completions" autocomplete="off" spellcheck="false" aria-describedby="model-url-help">
      <small id="model-url-help">填写完整的 Chat Completions 地址，以 /chat/completions 结尾。</small>
      <label for="model-name">模型名称（Model ID） <span>必填</span></label>
      <input id="model-name" v-model.trim="current.model" required placeholder="服务商提供的模型 ID" autocomplete="off" spellcheck="false">
      <div class="model-key-label"><label for="model-key">API Key</label><small>{{current.clear_key?'保存后清除':current.key_set?'已配置 · 留空不修改':'未配置'}}</small></div>
      <div class="model-key-input"><input id="model-key" v-model="current.api_key" :type="showKey?'text':'password'" autocomplete="new-password" :disabled="current.clear_key" :placeholder="addressChanged?'地址已变更，请重新填写对应密钥':current.key_set?'输入新密钥以替换现有密钥':'无鉴权的本地服务可留空'"><button type="button" :disabled="current.clear_key||!current.api_key" :aria-pressed="showKey" :aria-label="showKey?'隐藏新密钥':'显示新密钥'" @click="showKey=!showKey">{{showKey?'隐藏':'显示'}}</button></div>
      <label class="model-check"><input v-model="current.clear_key" type="checkbox">清除已保存密钥<span>无鉴权服务适用</span></label>
      <p v-if="addressChanged&&current.key_set&&!current.api_key&&!current.clear_key" class="model-warning">接口地址已变更：保存或测试时不会携带原密钥，请填写新地址对应的密钥。</p>
    </fieldset>
    <div class="model-guidance"><b>{{scope==='ocr'?'图片识别测试':'连接测试'}}</b><p>{{scope==='ocr'?'使用系统测试图片检查 image_url 支持，不发送你的 PDF。':'发送一条简短消息检查连接，不修改已保存的配置。'}}</p><small>密钥仅存服务器本地，不回显、不提交 Git。</small></div>
    <footer class="model-footer"><div class="model-feedback" aria-live="polite"><span v-if="error" class="model-error" role="alert">{{error}}</span><span v-else-if="notice" class="model-notice">✓ {{notice}}</span><span v-else>{{busy?(action==='test'?'正在测试，请稍候…':'正在保存…'):'切换用途会保留当前未保存的填写内容。'}}</span></div><div class="model-actions"><button type="button" :disabled="busy||!dirty" @click="reset">还原</button><button type="button" :disabled="busy" @click="submit(true)">{{action==='test'?'测试中…':'测试连接'}}</button><button class="model-save" type="submit" :disabled="busy||!dirty">{{action==='save'?'保存中…':'保存配置'}}</button></div></footer>
  </form>
  <div v-else class="model-loading"><p class="model-error" role="alert">{{error}}</p><button type="button" @click="load">重新加载</button></div>
</section>
</template>
<style scoped>
.model-settings{font-size:12px;color:var(--pop-ink);--model-line:#d3d8ce}.model-settings button{padding:8px 13px;border:1px solid #bdc6b9;background:#fffef9;border-radius:3px;cursor:pointer;font:inherit;min-height:35px}.model-settings button:disabled{opacity:.45;cursor:default}.model-scopes{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px}.model-scopes button{display:flex;gap:12px;align-items:center;padding:12px;text-align:left}.model-scopes button.active{background:#e4f6f6;border-color:#577f7b;box-shadow:inset 3px 0 #577f7b}.model-scope-icon{display:grid;place-items:center;width:34px;height:34px;flex:none;border:1px solid #b9cdc6;background:#fffef9;font:700 11px ui-monospace,monospace}.model-scopes b,.model-scopes small{display:block}.model-scopes small{font-size:10px;color:#758073;margin-top:5px}.model-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.model-heading b{font-size:13px}.model-heading>span{font-size:10px;color:#72806d}.model-heading .unsaved{color:#927015}.model-settings fieldset{border:0;margin:0;padding:0;min-width:0;display:grid;gap:8px}.model-settings fieldset>label,.model-key-label{margin-top:6px}.model-settings label{font-size:12px;color:#3a493e;padding:0;margin-bottom:0}.model-settings label>span{font-size:10px;font-weight:400;color:#8a9384;margin-left:7px}.model-settings input{box-sizing:border-box;width:100%;min-height:38px;margin:0;padding:9px 11px;border:1px solid #c4ccc0;border-radius:3px;font:12px ui-monospace,monospace;background:#fffef9;color:var(--pop-ink)}.model-settings fieldset>small{font-size:10px;color:#7a8475}.model-key-label{display:flex;align-items:center;justify-content:space-between}.model-key-label small{font-size:10px;color:#7b8975}.model-key-input{display:flex;gap:6px;min-width:0}.model-key-input input{flex:1;min-width:0}.model-key-input button{flex:none}.model-settings .model-check{display:flex;align-items:center;gap:7px;font-size:11px;margin-top:3px}.model-check input{width:13px;height:13px;min-height:0;margin:0;padding:0;accent-color:#577f7b}.model-check span{margin:0}.model-warning{margin:0;color:#8c671b;font-size:11px;line-height:1.6}.model-guidance{background:#f2f4ec;border-left:3px solid #b4c3a9;padding:10px 12px;margin:14px 0}.model-guidance b{font-size:11px}.model-guidance p{font-size:11px;color:#66745e;line-height:1.6;margin:4px 0}.model-guidance small{font-size:10px;color:#7b8572}.model-footer{position:sticky;bottom:-22px;padding:12px 0 4px;background:var(--pop-paper,#fffef9);border-top:1px solid var(--model-line);display:flex;align-items:center;gap:12px;z-index:2}.model-feedback{flex:1;min-width:0;font-size:11px;line-height:1.7;color:#7c8477;overflow-wrap:anywhere}.model-actions{display:flex;gap:7px;flex:none}.model-settings .model-save{background:var(--pop-yellow);border-color:var(--pop-ink);font-weight:700;box-shadow:2px 2px var(--pop-ink)}.model-error{color:#a22f42}.model-notice{color:#286445}.model-loading{padding:30px 10px;text-align:center;line-height:1.8;color:#758073}@media(max-width:600px){.model-scopes button{padding:9px;gap:8px}.model-scope-icon{width:28px;height:28px;font-size:10px}.model-footer{bottom:-16px;flex-direction:column;align-items:stretch}.model-actions{justify-content:flex-end}.model-check{flex-wrap:wrap}.model-key-label{gap:8px}}
.model-settings.model-settings input:focus{outline:2px solid #739b96!important;outline-offset:2px!important;box-shadow:none!important}
.model-settings{box-shadow:none!important}.model-settings fieldset>label:not(.model-check){display:flex!important;align-items:center;gap:6px;margin:4px 0 0!important}.model-settings .model-check{display:flex!important;align-items:center;gap:8px;margin:4px 0!important}.model-settings .model-check input{width:14px!important;height:14px!important;min-height:0!important;flex:none}.model-settings input:not([type=checkbox]){margin:0!important;min-height:38px}.model-footer{bottom:0;padding:12px 0;background:var(--ui-surface);flex-wrap:wrap}.model-scopes button>span:last-child{min-width:0}.model-guidance{margin:12px 0}.model-settings .model-heading{margin-bottom:8px}
</style>
